    const config = this.getConfig();
    const installedExtensionIds = new Set(vscode.extensions.all.map((extension) => extension.id.toLowerCase()));
    const { projects, suggestions } = await discoverWorkspace(config.projects, installedExtensionIds);
    this.lastProjects = projects;
    this.panel.webview.html = renderDashboard(projects, suggestions, config.refreshIntervalMs);
  }

  restartTimer(): void {
    if (!this.panel) {
