export async function discoverWorkspace(projectPaths: string[], installedExtensionIds = new Set<string>()): Promise<DiscoveryResult> {
  const canonicalPaths = [...new Set(await Promise.all(projectPaths.map(canonicalize)))];
  const trackedSet = new Set(canonicalPaths);
  const listeners = await listListeningProcesses();

  const projects = await Promise.all(canonicalPaths.map((projectPath) => buildProject(projectPath, listeners, installedExtensionIds)));
  projects.sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: "base" }));

