  if (hasUncommittedChanges) {
    return "Uncommitted changes";
  }
  if (ahead > 0 && behind > 0) {
    return `Diverged +${ahead}/-${behind}`;
  }
  if (ahead > 0) {
    return `${ahead} unpushed`;
  }
  if (behind > 0) {
    return `${behind} behind`;
  }
  return "Synced";
}

