function renderGitSummary(git: GitStatus): string {
  if (!git.hasGit) {
    return "No git";
  }

  return [
    escapeHtml(git.label),
    `remote ${git.hasRemote ? "yes" : "no"}`,
    `staged ${git.allChangesStaged ? "all" : git.hasStagedChanges ? "some" : "none"}`,
    `committed ${git.committed ? "yes" : "no"}`,
    `synced ${git.synced ? "yes" : "no"}`
  ].join(" | ");
}

function emptyGitStatus(): GitStatus {
  return {
    hasGit: false,
    hasRemote: false,
    hasStagedChanges: false,
    hasUnstagedChanges: false,
    hasUntrackedChanges: false,
    allChangesStaged: false,
    committed: false,
    hasUnpushedCommits: false,
    hasUnpulledCommits: false,
    synced: false,
    label: "No git"
  };
}

