function renderProjectCard(project: Project): string {
  const commands = project.suggestedCommands.length > 0 ? project.suggestedCommands.join(", ") : "No suggestion yet";

  return `<article class="card" data-project-path="${escapeAttr(project.path)}" data-parent-path="${escapeAttr(path.dirname(project.path))}">
    <div class="card-top">
      <div>
        <h2>${escapeHtml(project.name)}</h2>
        <div class="path">${escapeHtml(project.path)}</div>
      </div>
      <span class="badge ${project.status}">${escapeHtml(project.status)}</span>
    </div>
    <dl>
      <dt>Kind</dt>
      <dd>${escapeHtml(project.kind)}</dd>
      <dt>Git</dt>
      <dd>${renderGitSummary(project.git)}</dd>
      <dt>TODO</dt>
      <dd>${renderTodoSummary(project.todo)}</dd>
      ${
        project.kind === "static"
          ? ""
          : `<dt>Ports</dt><dd>${
              project.ports.length > 0
                ? project.ports
                    .map((port) => {
                      const url = `http://localhost:${port}`;
                      return `<a class="inline-link" href="${escapeAttr(url)}" data-command="openUrl" data-url="${escapeAttr(url)}">${port}</a>`;
                    })
                    .join(", ")
                : "None detected"
            }</dd>`
      }
      <dt>Evidence</dt>
      <dd>${project.evidence
        .map((item) =>
          item.path
            ? `<a class="inline-link" href="#" title="${escapeAttr(item.proof ?? "")}" data-command="openFile" data-path="${escapeAttr(item.path)}">${escapeHtml(item.label)}</a>`
            : escapeHtml(item.label)
        )
        .join(", ")}</dd>
      ${
        project.status === "running" || project.status === "serving" || project.status === "installed"
          ? ""
          : `<dt>Suggest</dt><dd>${escapeHtml(commands)}</dd>`
      }
      ${
        project.publishedRoutes.length > 0
          ? `<dt>Published</dt><dd>${project.publishedRoutes
              .map(
                (route) =>
                  `<a class="inline-link" href="${escapeAttr(route.url)}" data-command="openUrl" data-url="${escapeAttr(route.url)}">${escapeHtml(route.url)}</a>`
              )
              .join(", ")}</dd>`
          : ""
      }
    </dl>
    <div class="actions">
      <button class="secondary" data-command="openFolder" data-path="${escapeAttr(project.path)}">Open Folder</button>
    </div>
  </article>`;
}

function renderProjectRow(project: Project): string {
  const ports =
    project.ports.length > 0
      ? project.ports
          .map((port) => {
            const url = `http://localhost:${port}`;
            return `<a class="inline-link" href="${escapeAttr(url)}" data-command="openUrl" data-url="${escapeAttr(url)}">${port}</a>`;
          })
          .join(", ")
      : "None";

  return `<tr data-project-path="${escapeAttr(project.path)}" data-parent-path="${escapeAttr(path.dirname(project.path))}">
    <td><div class="table-name">${escapeHtml(project.name)}</div></td>
    <td><span class="badge ${project.status}">${escapeHtml(project.status)}</span></td>
    <td>${escapeHtml(project.kind)}</td>
    <td>${ports}</td>
    <td>${renderGitSummary(project.git)}</td>
    <td>${renderTodoSummary(project.todo)}</td>
    <td><div class="path">${escapeHtml(project.path)}</div></td>
    <td class="table-actions"><button class="secondary" data-command="openFolder" data-path="${escapeAttr(project.path)}">Open Folder</button></td>
  </tr>`;
}

function renderGitSummary(git: GitStatus): string {
  if (!git.hasGit) {
    return `<div class="git-summary"><span class="git-segment bad">No git</span></div>`;
  }

  const segments: string[] = [];
  if (git.hasUnstagedChanges) {
    segments.push(gitSegment("unstaged", false));
  } else if (git.hasStagedChanges) {
    segments.push(gitSegment("uncommitted", false));
  } else {
    segments.push(gitSegment("committed", true));
  }

  if (!git.hasRemote) {
    segments.push(gitSegment("no remote", false));
  } else if (git.hasUnpushedCommits) {
    segments.push(gitSegment("unpushed", false));
  } else if (git.hasUnpulledCommits) {
    segments.push(gitSegment("behind", false));
  } else if (git.synced) {
    segments.push(gitSegment("synced", true));
  } else {
    segments.push(gitSegment("unsynced", false));
  }

  return `<div class="git-summary">${segments.join("")}</div>`;
}

