export class Dashboard {
  private panel: vscode.WebviewPanel | undefined;
  private refreshInFlight: Promise<void> | undefined;
  private activeTab = "projects-view";
  private timer: NodeJS.Timeout | undefined;
  private lastProjects: Project[] = [];

  constructor(
    private readonly context: vscode.ExtensionContext,
    private getConfig: () => ProjectMonitorConfig
  ) {}

  open(pin = false): void {
    if (this.panel) {
      this.panel.reveal(vscode.ViewColumn.One);
      if (pin) {
        void this.pinPanel();
      }
      void this.refresh();
      return;
    }

    this.panel = vscode.window.createWebviewPanel(
      "projectMonitor.dashboard",
      "Project Monitor",
      vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true
      }
    );

    this.panel.onDidDispose(
      () => {
        this.panel = undefined;
        this.refreshInFlight = undefined;
        this.stopTimer();
      },
      undefined,
      this.context.subscriptions
    );

    this.panel.webview.onDidReceiveMessage(
      (message: DashboardMessage) => {
        void this.handleMessage(message);
      },
      undefined,
      this.context.subscriptions
    );

    this.panel.onDidChangeViewState(
      () => {
        if (this.panel?.visible) {
          this.syncTimerForActiveTab();
          void this.refresh();
        } else {
          this.stopTimer();
        }
      },
      undefined,
      this.context.subscriptions
    );

    this.syncTimerForActiveTab();
    void this.refresh();
    if (pin) {
      void this.pinPanel();
    }
  }

  async refresh(): Promise<void> {
    if (!this.panel) {
      return;
    }
    if (this.refreshInFlight) {
      return this.refreshInFlight;
    }

    this.refreshInFlight = this.refreshNow();
    try {
      await this.refreshInFlight;
    } finally {
      this.refreshInFlight = undefined;
    }
  }

  restartTimer(): void {
    if (!this.panel) {
      return;
    }
    this.syncTimerForActiveTab();
  }

  dispose(): void {
    this.stopTimer();
    this.panel?.dispose();
  }

  private startTimer(): void {
    this.stopTimer();
    if (!this.panel?.visible || this.activeTab === "suggestions-view") {
      return;
    }
  }

  private async revealFolder(folderPath: string): Promise<void> {
    const folder = vscode.Uri.file(folderPath);
    try {
      await vscode.commands.executeCommand("workbench.view.explorer");
      await vscode.commands.executeCommand("revealInExplorer", folder);
    } catch {
      await vscode.commands.executeCommand("vscode.openFolder", folder, { forceNewWindow: true });
    }
  }

