    }

    if (name === "proxy_pass") {
      const portMatch = value.match(/^(?:https?:\/\/)?(?:localhost|127\.0\.0\.1):(\d+)/);
      if (portMatch) {
        routes.push({ kind: "proxy", domain: serverContext.domain, locationPath, port: Number(portMatch[1]) });
