function renderProjectCard(project: Project): string {
  const commands = project.suggestedCommands.length > 0 ? project.suggestedCommands.join(", ") : "No suggestion yet";

  return `<article class="card" data-project-path="${escapeAttr(project.path)}" data-parent-path="${escapeAttr(path.dirname(project.path))}">
    <div class="card-top">
      <div>
        <h2>${escapeHtml(project.name)}</h2>
        <div class="path"><button class="path-button" data-command="openFolder" data-path="${escapeAttr(project.path)}">${escapeHtml(project.path)}</button></div>
      </div>
      <span class="badge ${project.status}">${escapeHtml(project.status)}</span>
    </div>
    <dl>
      <dt>Kind</dt>
      <dd>${escapeHtml(project.kind)}</dd>
      <dt>Git</dt>
      <dd>${renderGitSummary(project.git)}</dd>
      <dt>TODO</dt>
      <dd>${renderTodoSummary(project.todo, project.path)}</dd>
      ${
        project.kind === "static"
          ? ""
          : `<dt>Ports</dt><dd>${
              project.ports.length > 0
                ? project.ports
                    .map((port) => {
                      const url = `http://localhost:${port}`;
                      return `<a class="inline-link" href="${escapeAttr(url)}" data-command="openUrl" data-url="${escapeAttr(url)}">${port}</a>`;
                    })
                    .join(", ")
                : "None detected"
            }</dd>`
      }
      <dt>Evidence</dt>
      <dd>${project.evidence
        .map((item) =>
          item.path
            ? `<a class="inline-link" href="#" title="${escapeAttr(item.proof ?? "")}" data-command="openFile" data-path="${escapeAttr(item.path)}">${escapeHtml(item.label)}</a>`
            : escapeHtml(item.label)
        )
        .join(", ")}</dd>
      ${
        project.status === "running" || project.status === "serving" || project.status === "installed"
          ? ""
          : `<dt>Suggest</dt><dd>${escapeHtml(commands)}</dd>`
      }
      ${
        project.publishedRoutes.length > 0
          ? `<dt>Published</dt><dd>${project.publishedRoutes
              .map(
                (route) =>
                  `<a class="inline-link" href="${escapeAttr(route.url)}" data-command="openUrl" data-url="${escapeAttr(route.url)}">${escapeHtml(route.url)}</a>`
              )
              .join(", ")}</dd>`
          : ""
      }
    </dl>
  </article>`;
}

