  ) {
    this.statusBarItem.command = "projectMonitor.openDashboard";
    this.context.subscriptions.push(this.statusBarItem);
  }

  hasPanel(): boolean {
    return this.panel !== undefined;
  }

  open(pin = false): void {
    if (this.panel) {
